import csv
import io
import sys

from csvledger.errors import LedgerError


def quote_value(s):
    """Escape CR/LF so an echoed value stays on one line."""
    return s.replace("\r", "\\r").replace("\n", "\\n")


def read_records(path_str, kind_code, required_columns):
    """Validate the header eagerly; return an iterator of (line_num, dict)."""

    def fail(msg):
        return LedgerError(kind_code, msg)

    try:
        with open(path_str, "rb") as f:
            data = f.read()
    except OSError:
        raise fail(f"{path_str}: cannot read file") from None
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise fail(f"{path_str}: not valid UTF-8") from None

    csv.field_size_limit(sys.maxsize)
    reader = csv.reader(io.StringIO(text, newline=""))

    def next_record():
        try:
            return next(reader)
        except StopIteration:
            return None
        except csv.Error:
            raise fail(f"{path_str}:{reader.line_num}: malformed CSV") from None

    first = next_record()
    if first is None:
        raise fail(f"{path_str}: missing header")
    header = [c.strip().lower() for c in first]
    seen = set()
    for name in header:
        if name in seen:
            raise fail(f"{path_str}: duplicate column '{quote_value(name)}'")
        seen.add(name)
    for name in required_columns:
        if name not in seen:
            raise fail(f"{path_str}: missing column '{name}'")

    def rows():
        while True:
            rec = next_record()
            if rec is None:
                return
            if not rec:
                continue
            if len(rec) != len(header):
                raise fail(
                    f"{path_str}:{reader.line_num}: expected {len(header)} "
                    f"fields, got {len(rec)}"
                )
            yield reader.line_num, {h: v.strip() for h, v in zip(header, rec)}

    return rows()

